#pragma once
// The device's one system font, SF Compact, in six fixed text styles. Every
// screen draws text with it: themes, notifications and the firmware's own
// screens. There is no other font; a theme picks a style, not a font or size.
//
// Text is in display bytes (displayText below): printable ASCII,
// Cyrillic, the degree sign. The data is generated by tools/gen_system_font.py
// and lives in flash (SystemFontData.h); nothing here allocates.
#include <cstddef>
#include <cstdint>
#include <string>

namespace gm {

enum class TextStyle : uint8_t {
  Caption,    // 17 px Regular, every character
  Body,       // 22 px Medium, every character
  Headline,   // 28 px Medium, every character
  DisplayS,   // 48 px Medium, digits and  % + - . : °  (others from Headline)
  DisplayM,   // 70 px Medium, the same
  DisplayL,   // 96 px Semibold, the same
};
constexpr uint8_t TextStyleCount = 6;

// The style's name as themes write it: caption, body, headline, display-s,
// display-m, display-l. False for anything else.
bool textStyleFromName(const char* name, size_t length, TextStyle& out);
const char* textStyleName(TextStyle style);
// The style for a text layer that gives only a size (older themes).
TextStyle textStyleForSize(int size);

int styleSize(TextStyle style);         // em size in pixels
int styleBaseline(TextStyle style);     // from the top of the line
int styleLineHeight(TextStyle style);

// One glyph, ready to draw: ink box relative to the pen (left) and to the top
// of a line of the requested style (top), and its advance. A character the
// style lacks comes from Headline, moved onto this style's baseline; one no
// style has is drawn as a blank the width of a space.
struct GlyphView {
  const uint8_t* bitmap = nullptr;   // in flash, 2 bits per pixel
  uint8_t advance = 0, width = 0, height = 0;
  int16_t left = 0, top = 0;
};
void styleGlyph(TextStyle style, uint8_t character, GlyphView& out);
// Ink coverage, 0-255, of pixel (x, y) of the glyph's ink box.
uint8_t glyphCoverage(const GlyphView& glyph, int x, int y);

int styleTextWidth(TextStyle style, const char* text, size_t length);

// The whole font as one binary blob, for the web UI's theme preview renderer
// (GET /api/font), handed to `emit` in small pieces straight from flash.
// Layout, little-endian: "GMF1", style count; per style: glyph count, size,
// baseline, line height (u8 each), bitmap size (u16), the codes (u8 each),
// the glyphs (8 bytes each: offset u16, advance, width, height u8, left,
// top i8, 0), then the bitmap. Returns the total size.
typedef void (*FontSink)(void* context, const uint8_t* data, size_t length);
size_t writeSystemFont(FontSink emit, void* context);

// ---- Display bytes ----
// Text arrives as UTF-8 but is drawn one byte per character: printable ASCII
// stays as it is, Cyrillic (А-я, Ё, ё) and the degree sign take their
// Windows-1251 bytes (0xC0-0xFF, 0xA8, 0xB8, 0xB0), anything else becomes '?'.
std::string displayText(const std::string& utf8);
// The same into a fixed buffer, for callers that must not allocate: at most
// capacity - 1 display bytes plus a NUL, control characters dropped. Returns
// the number of bytes written.
size_t displayTextTo(char* out, size_t capacity, const char* utf8);
// Decodes the UTF-8 character at s[i] into its display byte and advances `i`
// past it. False (with `i` past the bad bytes) for a character the font cannot
// draw, malformed UTF-8, control characters and DEL.
bool decodeDisplayChar(const char* s, size_t size, size_t& i, uint8_t& out);

}  // namespace gm
